        JsonNode acceptanceValue = acceptance != null ? acceptance : precommit.path("experiment").has("acceptance") ? precommit.path("experiment").get("acceptance") : JSON.objectNode().put("phase", phase);
        JsonNode executorValue = executor != null ? executor : JSON.objectNode().put("execution_policy_sha256", text(execution.get("content_sha256"))).put("module", "strategy-research-next/4");
