        ObjectNode universe = JSON.objectNode(); universe.set("tradable_assets", LegacyResearchNext.strings(LegacyResearchNext.UNIVERSE)); universe.set("excluded_assets", LegacyResearchNext.strings(List.of("doge"))); universe.put("venue", "binance"); universe.set("instrument_scope", LegacyResearchNext.strings(LegacyResearchNext.EXECUTABLE_INSTRUMENTS));
